-- Official SAT Practice Tests (paper versions), generated by supabase/content/sat/build_sat.py. Do not edit by hand.
-- Run after migration 20261121000001_student_produced_responses.sql. Safe to re-run: existing exams are skipped.

select s.id, 'topic', v.name, v.ord from (values
  ('sat-math', 'Algebra', 1),
  ('sat-math', 'Advanced Math', 2),
  ('sat-math', 'Problem-Solving and Data Analysis', 3),
  ('sat-math', 'Geometry and Trigonometry', 4),
  ('sat-english', 'Craft and Structure', 1),
  ('sat-english', 'Information and Ideas', 2),
  ('sat-english', 'Standard English Conventions', 3),
  ('sat-english', 'Expression of Ideas', 4)
) as v(code, name, ord) join public.subjects s on s.code = v.code
on conflict (subject_id, kind, name) do nothing;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 8: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-8-reading-and-writing') then
    raise notice 'skipping sat-practice-test-8-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-8-reading-and-writing', 'SAT Practice Test 8: Reading and Writing', 'Official SAT Practice Test 8 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 216, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [220, 250], [220, 260], [230, 270], [230, 280], [240, 290], [240, 300], [250, 310], [260, 320], [270, 330], [300, 340], [310, 350], [320, 360], [330, 370], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 700], [670, 710], [680, 720], [690, 730], [700, 740], [710, 750], [720, 760], [730, 770], [740, 780], [760, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Juarez. In this context, “important” means marked by significant work or consequence. The text indicates that Juarez, who was the first president of Mexico from an Indigenous community, became a certain kind of figure in Mexico’s history. It then supports that claim by describing some of the “many significant accomplishments” from Juarez’s long tenure in office. This context conveys that Juarez is a significant and consequential figure in Mexico’s history."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on Juarez’s role as the first president of Mexico from an Indigenous community and on his many major accomplishments during his lengthy time in office; nothing in the text suggests that Juarez was “unpredictable,” or tended to behave in ways that couldn’t be predicted. Choice C is incorrect because nothing in the text suggests that Juarez was a particularly “secretive” figure, or that he tended to keep things private or hidden from others. Instead, the text focuses on things that are known about Juarez: that he was the first president of Mexico from an Indigenous community, that he had a lengthy tenure, and that his many major accomplishments included consolidating the national government’s authority and advancing Indigenous rights. Choice D is incorrect because the text focuses on the idea that Juarez, who was the first president of Mexico from an Indigenous community, had many major accomplishments during his lengthy time in office. Rather than suggesting that Juarez was an “ordinary,” or common and typical, figure in Mexico’s history, this context conveys that Juarez was instead a notable figure."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the research that Lopes-Ferreira and her colleagues are conducting on the stingray species Potamotrygon rex. As used in this context, “a substantial” effect means an effect that is sizable or noteworthy. The text indicates that the researchers are seeking to determine whether there are “considerable variations” in the potency of stingray venom that are associated with variation in the stingrays’ age and sex. This context suggests that the researchers want to find out whether stingray age and sex have a substantial effect on venom toxicity."}, {"type": "paragraph", "text": "Choice A is incorrect because there’s nothing in the text that suggests that the researchers have been studying whether the stingrays’ age and sex have “a disconcerting,” or an unsettling and disturbing, effect on the stingrays’ venom. The text indicates that the researchers wish to determine if stingray age and sex cause large variations in the toxicity of stingray venom, not if the effect of age and sex is disconcerting. Choice B is incorrect because the text indicates that researchers want to find out whether differences in stingray age and sex produce differences in stingray venom, not that the researchers want to find out whether age and sex have “an acceptable,” or a satisfactory, effect on venom. The text makes no mention of what would make an effect on venom toxicity acceptable and gives no indication that the researchers are interested in that question."}, {"type": "paragraph", "text": "Choice C is incorrect because it wouldn’t make sense in context for the researchers to be looking for “an imperceptible,” or an unnoticeable, effect of age and sex on stingray venom. The text says that the researchers are trying to determine if there are “considerable variations” in venom toxicity linked to age and sex, not that the researchers are trying to find effects that they can’t perceive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of how kelp forests help marine animals. In this context, “tranquil” means free from disturbance, or calm. The text indicates that ocean currents are powerful and make it difficult for marine animals to hide from predators and that kelp forests slow currents down to create calmer areas. In other words, kelp forests create a more tranquil environment."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that kelp forests provide shelter for marine animals, meaning they create environments that are safer, not more “dangerous.” Choice C is incorrect because the text discusses how kelp forests affect currents in the ocean, and it isn’t clear how an ocean environment could be “imaginative,” or full of imagination. Choice D is incorrect because the text indicates that kelp forests create a calm and safe environment, and an environment that is “surprising” would be characterized by unexpected occurrences, not calmness."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it logically and precisely completes the text’s discussion of The Mule Bone, a play that Zora Neale Hurston and Langston Hughes wrote together. In this context, “collaboration” means working together with someone to write a literary work. The text indicates that most writers prefer to work alone and that working together destroyed the friendship between Hurston and Hughes. This establishes that The Mule Bone is a relatively rare example of collaboration in literature."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “characterization” would mean a literary work’s portrayal of characters’ psychological experiences and motivations, but the text doesn’t discuss characterization in The Mule Bone specifically or in collaborative works more generally. Choice B is incorrect because in this context, “interpretation” would mean the explanation of a literary work’s meaning or significance, but the text doesn’t discuss how readers or critics have interpreted The Mule Bone; instead, the text discusses how the play was written collaboratively and how the writing process affected the two authors."}, {"type": "paragraph", "text": "Choice D is incorrect because in this context, “commercialization” would mean writing a literary work in such a way as to ensure its commercial appeal, but the text never discusses commercial appeal as a factor in the writing of The Mule Bone specifically or the writing of collaborative works more generally."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of how Ofelia Zepeda has contributed to the field of linguistics. As used in this context, “extensive” means having a wide or considerable extent. The text indicates that Zepeda’s many accomplishments in linguistics are varied, including teaching linguistics, writing poetry in more than one language, creating a grammar book, and co-founding a language institute. This context supports the idea that Zepeda’s contributions to the field are extensive."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence presents Zepeda’s accomplishments as examples to support the claim made in the first part of the sentence. It wouldn’t make sense to say that achievements as a professor, poet and author, and co-founder of a language institute demonstrate that Zepeda’s contributions in her field are “pragmatic,” or related to practical matters and not involving intellectual or artistic matters. Choice B is incorrect because the sentence presents Zepeda’s accomplishments as a professor, poet and author, and co-founder of a language institute as examples to support the claim made in the first part of the sentence. There’s no reason to believe that the positive achievements listed demonstrate that Zepeda’s contributions in her field are “controversial,” or have caused disputes and opposing viewpoints. Choice D is incorrect because in this context, “universal” would mean including or covering everything in a group. The sentence presents Zepeda’s accomplishments as examples to support the claim made in the first part of the sentence, and it wouldn’t make sense to say that these specific achievements—particularly as the author of a grammar book specific to the Tohono O’odham language—demonstrate that Zepeda’s contributions relate to everything in the field of linguistics."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes the main purpose of the text. The text states that archaeologists recently discovered a well-preserved food shop, or thermopolium, in Pompeii, Italy. The text then further describes the contents of the discovery and provides an example of what was found. Thus, the overall purpose of the text is to present a recent archaeological discovery."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text states that archaeologists found ancient artworks, it doesn’t compare these artworks to modern ones or to any other artworks. Choice B is incorrect. Although the archaeological discovery discussed in the text was made in Italy, the text doesn’t provide any information about politics or government in Italy. Choice D is incorrect because the text doesn’t discuss the climate where the archaeological discovery was made or in any other region."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately reflects the main purpose of the text. The text portrays Miss Pyne as awaiting the arrival of a carriage while Martha brings strawberries and flowers from the garden into the house. The text also describes the surroundings of the scene, stating that Miss Pyne looks “stately and calm,” the evening is bright and cool, and birds are singing in the garden as the sun sets. Then the last sentence states that the house was “wide open to the long-expected guest,” which strongly suggests that Miss Pyne’s anticipation and Martha’s activities were in preparation for the guest who is expected to arrive in the carriage. Thus, the text depicts the setting and conveys what these characters are doing as they await the arrival of their visitor."}, {"type": "paragraph", "text": "Choice A is incorrect because there is nothing in the text to indicate that the characters feel any worry about the guest’s arrival. The text indicates that the guest was “long-expected,“ but characterizing Miss Pyne as “stately and calm” conflicts with the idea that the characters are worried about the guest. Choice B is incorrect because the text describes a moment in time when two characters are awaiting the arrival of a visitor rather than an extended period over which characters could be seen changing. Choice C is incorrect. Although the text describes the activity indoors (Miss Pyne sitting calmly), it describes a higher level of activity, not stillness, outside (Martha bringing fruit and flowers and birds singing)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the overall structure of the text. The narrator begins by explaining how Charlot carefully delivers Atlante’s letter to Rinaldo, and then relates that Rinaldo feels “transported with joy” after reading the letter. Therefore, the overall structure of the text is best described as a description of the delivery of a letter followed by the portrayal of a character’s happiness after reading the letter."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that the letter has been written; there’s no explanation why another character hasn’t written one. In addition, the text’s description of Rinaldo “in a melancholy posture” suggests that he’s sad and thoughtful, not that he’s desperate to receive the letter. Choice C is incorrect. Although the text states that Charlot won’t toss the letter to Rinaldo because she doesn’t want it to fall, the text doesn’t refer to the contents of the letter. Instead, the text describes how happy Rinaldo feels after reading it. Choice D is incorrect. Although the text does describe Rinaldo’s reaction to the letter, the text doesn’t begin by discussing Atlante’s inspiration for writing the letter. Instead, the text begins by discussing the delivery of the letter."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it best describes how the underlined portion functions in the text as a whole. The text says that the increased production quotas of food processing companies during World War II enabled employees to make better bargains in exchange for their labor. The underlined portion presents an example of this increased bargaining power: employees requested more favorable benefits, and employers complied because they were under pressure to fulfill the demanding terms of their contracts. Thus, the underlined portion of the text elaborates on a claim about labor relations in a particular industry (food processing) made earlier in the text."}, {"type": "paragraph", "text": "Choice B is incorrect because there is no indication in the text that the economic factors that influenced food processing also influenced other parts of the economy; thus, the bargaining described in the underlined portion of the text cannot be called an example of a trend. Choice C is incorrect because the underlined portion supports the historical narrative of labor activism in food processing that is sketched in the text, instead of noting an exception to that narrative. Choice D is incorrect because while the underlined portion does discuss the demands that workers made in exchange for their labor, it does not discuss the identities of the workers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, why was Wang and his team’s discovery of the Terropterus xiushanensis fossil significant?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it states why Wang and his team’s discovery of the Terropterus xiushanensis fossil was significant. The text explains that up until Wang and his team’s discovery, the only fossil evidence of mixopterids came from the paleocontinent of Laurussia. Wang and his team, however, identified fossil remains of a mixopterid species from the paleocontinent Gondwana. Therefore, the team’s discovery was significant because the fossil remains of a mixopterid species were outside of the paleocontinent Laurussia."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text states that Wang and his team identified fossilized remains of a mixopterid species that lived more than 400 million years ago, it doesn’t indicate that mixopterid fossils previously found by scientists dated to a more recent period than that. Choice B is incorrect. Although the text states that mixopterids are related to modern arachnids and horseshoe crabs, it doesn’t suggest that the fossil discovered by Wang and his team confirmed that this relationship is closer than scientists had previously thought. Choice C is incorrect because the team’s fossil established the presence of mixopterids on Gondwana, not on Laurussia. Moreover, the text only discusses the fossil in relation to the geographical distribution of mixopterids, not in relation to their evolution."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most effectively uses data from the table to complete the statement about video game availability. The text states that just a few games released in the past are available today and then indicates that there is a period of years from which only 14.22 percent of the games released are available. The table shows that 14.22 percent of games are still available from the years 1995–1999."}, {"type": "paragraph", "text": "Choice A is incorrect because the years 2000–2004 are not represented in the table. Choice C is incorrect because the years 1970–1974 are not represented in the table. Choice D is incorrect because the years 1985–1989 correspond to a percentage of games still available of 15.38 percent, not 14.22 percent."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the information in the table, at what depth does the southern stoplight loosejaw live?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The table shows the depths below the ocean surface at which four species of deep-sea fish live. According to the table, the range of depths at which the southern stoplight loosejaw lives is 500–2,000 meters below the surface."}, {"type": "paragraph", "text": "Choice A is incorrect because the table indicates that the southern stoplight loosejaw lives 500–2,000 meters below the ocean surface, not at depths more than 2,000 meters below the surface. Choice B is incorrect because the table indicates that the southern stoplight loosejaw lives 500–2,000 meters below the ocean surface, not 150–400 meters below the surface. Choice D is incorrect because the table indicates that the southern stoplight loosejaw lives 500–2,000 meters below the ocean surface, not 250–500 meters below the surface."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it effectively uses data from the table to complete the statement, identifying the month in which the United States had the highest number of housing starts in 2022. According to the table, which shows the number of US housing starts from January to April 2022, the highest number of housing starts was 1,803 thousand, which occurred in April."}, {"type": "paragraph", "text": "Choice B is incorrect because March had 1,713 thousand housing starts, which is lower than the number of starts in April and in February. Choice C is incorrect because January had 1,669 thousand housing starts, which is the lowest of all the months listed in the table. Choice D is incorrect because February had 1,771 thousand housing starts, which is lower than the number of starts in April."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the student’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would support the claim about Chambi’s photographs. The text describes a student advancing the claim that Chambi’s photographs “have considerable ethnographic value”—meaning that they are valuable as records of cultures—and that they “capture diverse elements of Peruvian society” in a respectful way. If it’s true that Chambi carefully photographed people from a range of different communities in Peru as well as photographed the customs and sites of different communities, that would lend support to the claim that the photographs have ethnographic value as depictions of diverse elements of society in Peru."}, {"type": "paragraph", "text": "Choice B is incorrect because the student’s claim is that Chambi’s photographs have considerable ethnographic value because they depict diverse elements of Peruvian society; the student doesn’t claim anything about the technical skill demonstrated in the photographs. Choice C is incorrect because neither Chambi’s reputation nor the locations where his photographs may have been published would be relevant to the student’s claim that his photographs are valuable as an ethnographic record of Peru’s diverse society. Choice D is incorrect because the popularity among other photographers of the people and places that Chambi photographed would be irrelevant to the student’s claim that Chambi’s photographs are valuable as an ethnographic record of Peru’s diverse society."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would most directly support the researchers’ hypothesis about the connection between the dusky shark population decline and the eastern oyster population decline. The text indicates that although dusky sharks don’t usually eat eastern oysters, they do consume cownose rays, which are the main predators of eastern oysters. An increase in the abundance of cownose rays in the region in response to a decline in the abundance of dusky sharks would directly support the researchers’ hypothesis: a higher number of cownose rays would consume more eastern oysters, driving down the oyster population."}, {"type": "paragraph", "text": "Choice A is incorrect because a finding that there’s an association between a decline in the regional abundance of some of dusky sharks’ prey and the regional abundance of dusky sharks wouldn’t directly support the researchers’ hypothesis that a decline in dusky sharks has led to a decline in eastern oysters in the region. Although such a finding might help explain why shark abundance has declined, it would reveal nothing about whether the shark decline is related to the oyster decline. Choice B is incorrect because a finding that eastern oyster abundance tends to be greater when dusky sharks and cownose rays are present than when only dusky sharks are present wouldn’t support the researchers’ hypothesis that a decline in dusky sharks has led to a decline in eastern oysters in the region. The text indicates that the sharks prey on the rays, which are the main predators of the oysters; if oyster abundance is found to be greater when rays are present than when rays are absent, that would suggest that rays aren’t keeping oyster abundance down, and thus that a decline in rays’ predators, which would be expected to lead to an increase in the abundance of rays, wouldn’t bring about a decline in oyster abundance as the researchers hypothesize. Choice C is incorrect because a finding that consumption of eastern oysters by cownose rays increased substantially before dusky sharks declined in regional abundance wouldn’t support the researchers’ hypothesis that the decline in dusky sharks has led to a decline in eastern oysters in the region. Such a finding would suggest that some factor other than shark abundance led to an increase in rays’ consumption of oysters and thus to a decrease in oyster abundance, thereby weakening the researchers’ hypothesis."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a finding that, if true, would support the researchers’ hypothesis about the plants’ dependence on dissolving rock. The text indicates that the roots of the two plant species grow directly into quartzite rock, where hairs on the roots secrete acids that dissolve the rock. The researchers hypothesize that the plants depend on this process because dissolving rock opens spaces for the roots to grow and releases phosphates that provide the plants with phosphorus, a vital nutrient. If the plants carry out this process of dissolving rock even when the rock already has spaces into which the roots could grow, that would support the researchers’ hypothesis because it suggests that the plants are getting some advantage—such as access to phosphorus—from the action of dissolving rock. If the plants don’t benefit from dissolving rock, they would be expected to grow in the cracks that already exist, as doing so would mean that the plants don’t have to spend energy creating and secreting acids; if, however, the plants create new entry points by dissolving rock even when cracks already exist, that would support the hypothesis that they depend on dissolving rock for some benefit."}, {"type": "paragraph", "text": "Choice A is incorrect because the existence of soil-inhabiting members of the Velloziaceae family with similar root structures to those of the two species discussed in the text wouldn’t support the researchers’ hypothesis that the species discussed in the text depend on dissolving rock. If other such members exist, that might suggest that the root structures can serve more functions than secreting acids to dissolve rock (since dissolving rock may not be necessary for plants living in soil), but that wouldn’t suggest anything about whether the species discussed in the text benefit from dissolving rock. Choice B is incorrect because differences in the proportions of citric and malic acid secreted by the two species would be irrelevant to the hypothesis that the plants depend on dissolving rock. There’s no information in the text to suggest that the proportion of each acid has any bearing on the process of dissolving rock or on any benefits the plants might receive from that process. Choice D is incorrect because if the two species thrive on rocks without phosphates, that would weaken the researchers’ hypothesis that the plants depend on dissolving rock partly because dissolving rock gives them access to phosphates. If the plants can survive on rocks without getting a vital nutrient by dissolving those rocks, then either the nutrient isn’t actually vital for those plants or they can get the nutrient in some way other than by dissolving rocks."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of mosquito repellents. The text begins by explaining that many repellents work by using natural components to activate multiple odor receptors on mosquitoes’ antennae, and that new repellents must be created whenever mosquitoes become resistant to older ones. The text then highlights a research team’s discovery that EBF, a molecular component of a chrysanthemum-flower extract, can repel mosquitoes by activating a single odor receptor, Or31, that is shared by all species of mosquitoes known to carry diseases. The text suggests that compared to the repellents mentioned earlier, a repellent that acts on the Or31 receptor would be more effective: by noting that all mosquito species known to carry diseases share the Or31 receptor, the text suggests that the Or31 receptor may be unique in this respect, meaning that a repellent such as EBF that acts on it would be more effective since it works on a single receptor shared by all mosquito species that carry diseases, rather than a combination of receptors that is not shared by all species. Once mosquitoes become resistant to EBF, it would therefore make sense for researchers to look for other molecular components similar to EBF that target the activation of Or31 receptors, since a single such component could also repel all disease-carrying mosquitoes."}, {"type": "paragraph", "text": "Choice B is incorrect because nothing in the text suggests that EBF molecules are difficult to extract from chrysanthemums and that investigating alternative extraction methods would therefore be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, since that component targets the Or31 odor receptor shared by all species of mosquitoes known to carry diseases. Choice C is incorrect because nothing in the text suggests that researchers are unaware of the precise location of Or31 and other odor receptors in mosquitoes’ antennae or that knowing this information would be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, which targets the Or31 odor receptor. Choice D is incorrect because it doesn’t logically follow that the discovery of one odor receptor shared by all disease-bearing mosquitoes should lead to further research into which repellents might activate the greatest number of odor receptors. Rather, the text suggests that researchers developing new mosquito repellents should instead search for additional molecular components that, like EBF, activate the one odor receptor that is known to be shared by all disease- bearing mosquitoes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of Shultz’s finding about male tanagers. The text explains that because carotenoids both contribute to deeply saturated feathers and offer health benefits, having deeply saturated feathers is usually “an honest signal” (a true indication) that a bird is generally fit. However, Shultz and others have found that certain male tanagers can appear to have deeply saturated feathers even if they haven’t consumed a diet rich in carotenoids, thanks to microstructures in their feathers that manipulate light. If those birds aren’t necessarily eating carotenoid- rich diets, they may actually be less fit than other birds that appear to have similarly saturated feathers; this suggests that a male tanager’s appearance may function as a dishonest signal, or a false indication, of the bird’s overall fitness."}, {"type": "paragraph", "text": "Choice A is incorrect because Shultz’s finding suggests that some tanagers can signal fitness without consuming the carotenoids that contribute to fitness, thereby making those signals dishonest, not that tanagers can give honest signals of their fitness without consuming carotenoids. Choice B is incorrect because Shultz’s finding suggests that the microstructures in certain tanagers’ feathers can give a dishonest signal of fitness, not that the microstructures are less effective than actual pigmentation for signaling fitness. Whether the signal of fitness is honest or dishonest has no bearing on how effective the signal is: a signal is effective if potential mates behave as though it’s true, regardless of whether it’s actually true. Since there’s no information in the text about how potential mates respond to the dishonest signals of some tanagers, there’s no support for the idea that the dishonest signals are less effective than the honest signals. Choice C is incorrect because Shultz’s finding suggests that certain male tanagers may appear to be fitter than they actually are, not that scientists haven’t determined why tanagers prefer mates with colorful appearances."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb “has been” agrees in number with the singular subject “writing.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “writing.” Choice B is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “writing.” Choice D is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “writing.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of non-finite (untensed) verb forms in a sentence. The modal “would,” which indicates the future from a perspective in the past, should be accompanied by a non-finite plain form verb. In this choice, the non-finite plain form verb “create” is used correctly in conjunction with the non-finite plain form verb “increase” to describe what the lock would do."}, {"type": "paragraph", "text": "Choice A is incorrect because the finite present tense verb “creates” can’t be used in this way with the modal “would” to describe what the lock would do."}, {"type": "paragraph", "text": "Choice C is incorrect because the present participle “creating” can’t be used in this way with the modal “would” to describe what the lock would do. Choice D is incorrect because the finite past tense verb “created” can’t be used in this way with the modal “would” to describe what the lock would do."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation around noun phrases. No punctuation is needed because the coordinated noun phrase “Thomas Hart Benton and Jackson Pollock” is a restrictive appositive, meaning that it provides essential identifying information about the noun phrase before it, “the renowned twentieth-century US artists.”"}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the noun phrase “the renowned twentieth-century US artists” and the restrictive appositive “Thomas Hart Benton and Jackson Pollock.” Additionally, no punctuation is needed between the sentence’s subject (“paintings by the renowned twentieth- century US artists Thomas Hart Benton and Jackson Pollock”) and the main verb (“were featured”). Choice C is incorrect because no punctuation is needed between the coordinated elements “Thomas Hart Benton” and “Jackson Pollock.” Additionally, no punctuation is needed between the sentence’s subject (“paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollock”) and the main verb (“were featured”). Choice D is incorrect because no punctuation is needed between the noun phrase “the renowned twentieth- century US artists” and the restrictive appositive “Thomas Hart Benton and Jackson Pollock.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation to mark boundaries between supplements and clauses. The comma after “equations” is used to separate the independent clause (“Hopper’s… equation”) from the supplementary adverb phrase “though.” The colon after “though” is used to mark the boundary between the clause ending with “though” and the following clause (“as…age”). A colon used in this way introduces information that illustrates or explains information that has come before it. In this case, the colon after “though” introduces the following explanation of how Hopper’s subsequent career would involve more than just solving equations: she would become a pioneering computer programmer."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a comma splice. A comma can’t be used in this way to join two independent clauses (“Hopper’s…though” and “as… age”) such as these. Choice C is incorrect because it results in an illogical sequence of sentences. Placing the period after “equations” and beginning the next sentence with “Though” illogically suggests that the following information (that Hopper would help usher in the digital age) is contrary to the information in the previous sentence (Hopper’s subsequent career would involve more than just solving equations). Instead, the information that follows supports the information from the previous sentence by explaining how her work and influence extended beyond solely solving equations. Choice D is incorrect because it results in a run-on sentence. The two independent clauses (“Hopper’s…though” and “as…age”) are fused without punctuation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb “attest” agrees in number with the plural subject “trailblazing accomplishments.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the singular verb “attests” doesn’t agree in number with the plural subject “trailblazing accomplishments.” Choice B is incorrect because the singular verb “has attested” doesn’t agree in number with the plural subject “trailblazing accomplishments.” Choice C is incorrect because the singular verb “is attesting” doesn’t agree in number with the plural subject “trailblazing accomplishments.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the punctuation of a supplementary phrase following a clause. This choice uses a comma to separate the supplementary adverb phrase “however” from the independent clause it modifies (“They…antiquity”) and uses a semicolon to join the first independent clause (“They…antiquity”) and the second independent clause (“some…literature”). Further, placing the semicolon after “however” indicates that the information in the clause that this is part of (that neoclassical writers were not the first to adopt classical literary modes) is contrary to what might be assumed from the information in the previous sentence (that the neoclassical writers were unique in imitating classical epic poetry and satires)."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to mark the boundary after “however” between the two independent clauses with appropriate punctuation. Choice B is incorrect because the comma after “however” can’t be used in this way to mark the boundary between the two independent clauses. Choice D is incorrect because placing the semicolon after “antiquity” illogically indicates that the information in the clause that this is part of (that prominent Renaissance figures were also influenced by classical literature) is contrary to the information in the previous clause (that neoclassical writers were not the first to adopt classical literary modes)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation and verb forms within a sentence. This choice leaves the verb “admired” in its nonfinite past participle form to function within a supplementary element (“much…followed”). Offset by commas after “works” and “followed,” this supplementary element interrupts the main clause (“English poet and Shakespeare contemporary John Donne’s works…had…been essentially gathering dust…”) with additional information about the works’ reception during Donne’s lifetime."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to offset the supplementary element (“much…followed”) with appropriate punctuation, and using the finite verb “were much admired” results in an ungrammatical sentence. Choice B is incorrect because using the finite verb “were much admired” results in an ungrammatical sentence. Choice D is incorrect because it fails to offset the supplementary element (“much…followed”) with appropriate punctuation, and using the finite verb “had been much admired” results in an ungrammatical sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes “silica glass’s atomic arrangement” the subject of the sentence and places it immediately after the modifying phrase “compared to that of alumina glass.” In doing so, this choice clearly establishes that silica glass’s atomic arrangement—and not another noun in the sentence—is being compared to the atomic arrangement (“that”) of alumina glass."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase “silica glass” immediately after the modifying phrase illogically suggests that silica glass itself (rather than its atomic arrangement) is being compared to alumina glass’s atomic arrangement. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “silica glass” immediately after the modifying phrase illogically suggests that silica glass itself (rather than its atomic arrangement) is being compared to alumina glass’s atomic arrangement. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “a significant disadvantage” immediately after the modifying phrase illogically suggests that “a significant disadvantage” is being compared to alumina glass’s atomic arrangement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Still” logically signals that the information about Sher-Gil in this sentence—that she longed to leave Paris and return to India— contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris in the previous sentences."}, {"type": "paragraph", "text": "Choice B is incorrect because “therefore” illogically signals that the information about Sher-Gil in this sentence is a result or consequence of the descriptions in the previous sentences. Instead, this information contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris. Choice C is incorrect because “indeed” illogically signals that the information about Sher-Gil in this sentence offers additional emphasis in support of the descriptions in the previous sentences. Instead, this information contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris. Choice D is incorrect because “furthermore” illogically signals that the information about Sher-Gil in this sentence offers additional support for or confirmation of the descriptions in the previous sentences. Instead, this information contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Specifically” logically signals that the information in this sentence—that Molina and Rowland’s research laid the foundation for a later treaty—provides specific, precise details elaborating on the previous sentence’s more general claim about the influence of the research."}, {"type": "paragraph", "text": "Choice A is incorrect because “regardless” illogically signals that the information in this sentence is true despite the previous sentence’s claim about the influence of Molina and Rowland’s research. Instead, this information—that the research laid the foundation for a later treaty—provides specific details elaborating on the previous claim. Choice C is incorrect because “however” illogically signals that the information in this sentence contrasts with the previous sentence’s claim about the influence of Molina and Rowland’s research. Instead, this information—that the research laid the foundation for a later treaty—provides specific details elaborating on the previous claim. Choice D is incorrect because “earlier” illogically signals that the information in this sentence occurred at a time before Molina and Rowland’s research influenced the fight against CFCs. Instead, this information—that the research laid the foundation for a later treaty—provides specific details elaborating on the previous claim about the research’s influence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “Indeed” logically signals that the description of the art installation in this sentence—its blue room and preening unicorn that leave visitors “dazzled and confused”—offers additional emphasis in support of the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.”"}, {"type": "paragraph", "text": "Choice A is incorrect because “second” illogically signals that the description in this sentence is a second, separate claim from the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.” Instead, the specific details describing the installation emphasize and support the previous claim. Choice B is incorrect because “instead” illogically signals that the description in this sentence is an alternative to the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.” Rather, the specific details describing the installation emphasize and support that claim. Choice D is incorrect because “nevertheless” illogically signals that the description in this sentence is true despite the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.” Instead, the specific details describing the installation emphasize and support that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes the distance covered by the Philadelphia and Lancaster Turnpike, noting that the turnpike, which connected the two Pennsylvania cities in its name, was sixty-two miles long."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence emphasizes the significance of the turnpike; it doesn’t emphasize the distance that the turnpike covered. Choice C is incorrect. While the sentence mentions that the turnpike connected two Pennsylvania cities, it doesn’t emphasize the specific distance covered by the turnpike. Choice D is incorrect. The sentence emphasizes when the turnpike was built; it doesn’t emphasize the distance that the turnpike covered."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes the aim, or goal, of the research study, noting what Terada set out to do: determine whether some of the Moon’s oxygen was coming from Earth."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence focuses on how the Kaguya satellite collected data; it doesn’t emphasize the aim of the research study. Choice B is incorrect. While the sentence mentions what Terada was curious about before conducting the research study, it doesn’t emphasize his study’s aim. Choice D is incorrect. The sentence presents the research study’s conclusion; it doesn’t emphasize the study’s aim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes the aim of the research study by highlighting what the researchers conducting the study wanted to know—specifically, which factors influence clutch size among lizards."}, {"type": "paragraph", "text": "Choice B is incorrect because the sentence emphasizes what researchers determined at the end of the study, not what the study’s aim was. Choice C is incorrect because the sentence emphasizes a finding from the research study, not the aim of the study. Choice D is incorrect because the sentence emphasizes the research study’s methodology, not its aim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence uses information from the notes to make a generalization about the kind of study Glickman, Brown, and Song conducted. Specifically, the sentence indicates that the study was of a kind that used statistical methods to address questions of authorship within the field of music."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence summarizes the methodology and findings of a particular analysis of a single song; it doesn’t make a generalization about the kind of study conducted. Choice B is incorrect because the sentence mentions the data and conclusion of a particular analysis of a single song; it doesn’t make a generalization about the kind of study conducted. Choice C is incorrect because the sentence focuses on a specific conclusion from a particular analysis of a single song; it doesn’t make a generalization about the kind of study conducted."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best completes the text’s discussion of how viewers respond to colors. The text presents something art scholars have noted and gives the example of people tending to find paintings with blues and greens more appealing than those with yellows and oranges. This context conveys that certain colors are more “attractive to” viewers than other colors are."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates only that people tend to find some colors more appealing than others and gives no indication that certain colors are ever “confusing for,” or puzzling to, viewers. Choice C is incorrect because the text discusses the relative appeal of certain colors in paintings but gives no indication that any colors would ever be “corrected by” viewers, or somehow fixed or improved by them. Choice D is incorrect because it wouldn’t make much sense to say that some colors are more “similar to” viewers than others, which would suggest that colors and viewers are alike to different degrees. Further, the text primarily emphasizes a difference, not a similarity, in how appealing paintings tend to be based on the colors they contain."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of how biodiversity loss due to invasive species can be avoided. As used in this context, “preventable” means able to be stopped or kept from happening. The text indicates that “people can take simple steps” to avoid bringing possible invasive species into new environments. It presents these steps as an example of how biodiversity loss due to invasive species is preventable."}, {"type": "paragraph", "text": "Choice B is incorrect because it wouldn’t make sense to say that a simple step like washing your shoes after traveling is an example of biodiversity loss due to invasive species being “undeniable,” or something that can’t be proved to be wrong. Although the text may suggest that biodiversity loss due to invasive species is something that really happens, the word that completes the text must make the first sentence into an assertion that is illustrated by the second sentence, and the second sentence illustrates the idea that biodiversity loss due to invasive species is preventable, not undeniable. Choice C is incorrect because it wouldn’t make sense to say that a simple step like washing your shoes after traveling is an example of biodiversity loss due to invasive species being “common,” or something that happens regularly. Additionally, the text doesn’t provide any information about how frequently invasive species cause biodiversity loss. Choice D is incorrect because it wouldn’t make sense to say that a simple step like washing your shoes after traveling is an example of biodiversity loss due to invasive species being “concerning,” or something that is troubling or causes worry. Although the text implies that the phenomenon of biodiversity loss due to invasive species is itself a concerning phenomenon, the word that completes the text must make the first sentence into an assertion that is illustrated by the second sentence, and the second sentence illustrates the idea that biodiversity loss due to invasive species is preventable, not concerning."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion about recycling plastics. In this context, “inadequate” means not satisfactory. The text indicates that the mechanical plastic-recycling process affects the environment and causes “the loss of material quality.” The text contrasts that with Chazovachii’s chemical plastic-recycling process, which is cleaner and produces a desirable product. The text’s emphasis on the negative aspects of mechanical recycling suggests that it is inadequate in terms of environmental impact and the quality of the material the process yields."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context “resilient” would mean able to withstand difficulty and the text does not characterize the plastic-recycling process as having this quality or describe any difficulties that these processes might need to overcome. Choice C is incorrect because in this context “dynamic” would mean constantly changing. Although the text suggests that there have been changes in the field of recycling, as is the case with the advent of Chazovachii’s chemical recycling process, there is nothing to suggest that the mechanical process itself has changed or is prone to change. Choice D is incorrect because in this context “satisfactory” would mean acceptable but not perfect. The text mentions only shortcomings of the mechanical process (environmental effects and lower material quality), so the text more strongly supports a negative view of this process and provides no evidence that it would be considered satisfactory."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the Three Sisters intercropping system. As used in this context, “intricate” would mean made up of complexly related elements. The text indicates that in the Three Sisters system, maize, squash, and beans form a “web of relations” in which the crops interact in various ways. The text’s description of these interactions—the bean vines growing on the maize stalks, the squash vines keeping weeds away, and the beans adding nutrients that the maize and squash use—provides context suggesting that this “web of relations” is intricate."}, {"type": "paragraph", "text": "Choice A is incorrect because describing the relationship among the crops in the Three Sisters system as “indecipherable,” or impossible to comprehend, would not make sense in context. Although the text presents the relationship as complex, the text’s description of the role that each crop plays makes it clear that the relationship is well understood, not indecipherable. Choice B is incorrect because the text discusses the practical benefits that each plant in the Three Sisters system provides to other members of the system, showing that the relationship among the crops that make up the system is not “ornamental,” or mainly serving a decorative purpose. Choice C is incorrect because describing the relationship among the crops in the Three Sisters system as “obscure,” or unknown or poorly understood, would not make sense in context. Although the text presents the relationship as complex, the text’s description of the role that each crop plays makes it clear that the relationship is well understood, not obscure."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of baleen whale accessory spleens. In this context, “latent” means dormant or functionless. The text sets up a contrast between the idea that baleen whale accessory spleens appear not to have a function and the research indicating that the accessory spleen may actually have a role in supporting the whales’ diving mechanisms. This context therefore conveys the idea that the assumption that baleen whale accessory spleens are latent may be incorrect."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense to say that the role of the accessory spleen is “replicable,” or capable of being reproduced. The text indicates that the role of the accessory spleen seems to have no function, but some researchers think it does have a role; the text doesn’t address whether the role of the accessory spleen could or couldn’t be reproduced. Choice B is incorrect because suggesting that the role of the accessory spleen is “predetermined,” or decided in advance, wouldn’t make sense in context. Although the researchers may agree that the role of the accessory spleen or any other organ hasn’t been determined in advance, the text focuses on the idea that the accessory spleen was thought to have been functionless but may in fact serve an active role for baleen whales. Choice C is incorrect because it’s the opposite of what the context of the text is conveying. The second sentence of the text indicates that baleen whale accessory spleens may not be useless, not that they aren’t “operative,” or functional."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately states the main purpose of the text. After providing a brief introduction to computer scientist Luis von Ahn, the text focuses on discussing how von Ahn’s digitization work led to the invention of a digital security test known as reCAPTCHA."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t address how digital scanners work."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the text mentions von Ahn’s book-digitizing project, that information is provided as a detail, not as the main purpose of the text. Choice D is incorrect because the text doesn’t provide any indication of reCAPTCHA’s popularity; instead, it describes reCAPTCHA’s origin."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes the overall structure of the text. Throughout the text, the speaker characterizes nighttime as if it were a person who wears clothing (“a garment” that is “velvet soft” and “violet blue”) and a veil “over her face” and who moves her hands “slowly with their gem-starred light” through her dark hair. Thus, the text is structured as an extended comparison of night to a human being."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never mentions any particular location; instead, it focuses on presenting a single description of night as a person with certain clothing and features. Choice B is incorrect because the text doesn’t make any reference to the sun or sunrise; instead, it focuses on presenting a single image of night as a person with certain clothing and features. Choice D is incorrect. Rather than describing how nighttime changes seasonally (or in any other way), the text presents a single image of night as a person with certain clothing and features."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately portrays the main purpose of the text. At the beginning of the text, Tom asserts that he and the other people staging the play are doing so only for “a little amusement among ourselves” and aren’t interested in attracting an audience or any attention with the production. Then, Tom promises that the play they chose is modest and appropriate, and he further reasons that using the well-written prose of “some respectable author” is better than using their own words. Overall, the main purpose of the text is to convey Tom’s promise that the play will be inoffensive and involve only a few people."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t indicate that Tom had earlier intentions for the play’s performance or that anything has changed since the group first decided to stage a play. Instead, the text focuses on how harmless the entire endeavor will be. Choice C is incorrect. Although Tom mentions that using the words of a “respectable author” will be better than using their own words, he never addresses the idea that the people around him generally aren’t skilled enough to stage a play. Choice D is incorrect because in the text Tom specifically says that they “want no audience, no publicity,” which indicates that they don’t plan on promoting the play at all."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Behrenfeld and colleagues (Text 2) most likely respond to the “conventional wisdom” discussed in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because based on Text 2, it represents how Behrenfeld and colleagues would most likely respond to the “conventional wisdom” discussed in Text 1. The conventional wisdom cited holds the opinion that when there is species diversity within a phytoplankton population, “one species should emerge after outcompeting the rest”—that is, after being so successful in competing for resources that the other species vanish from the population. However, Text 2 explains that according to Behrenfeld and colleagues, phytoplankton are so small and spaced so far apart in the water that there is “much less” direct competition for resources within phytoplankton populations than scientists had previously thought."}, {"type": "paragraph", "text": "Choice B is incorrect because Text 2 never discusses whether routine replenishment of ocean nutrients affects competition between phytoplankton species. Choice C is incorrect because the interspecies competition discussed in both texts is specifically between phytoplankton species, and neither text considers whether phytoplankton compete for resources with larger nonphytoplankton species. Choice D is incorrect because according to Text 2, Behrenfeld and colleagues argue that water density decreases, not increases, competition between phytoplankton species."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what did the narrator and Mario do while riding in the car?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes what the narrator and Mario did while riding in the car. The text describes a car trip that the narrator is taking with her family. The text states that during the car ride, the narrator and Mario “played games” to see how many different license plates they could spot."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention the narrator and Mario reading during the car ride and instead describes them playing games. Choice B is incorrect because the text doesn’t mention the narrator and Mario singing songs during the car ride and instead describes them playing games. Choice C is incorrect because the text doesn’t mention the narrator and Mario sleeping during the car ride and instead describes them playing games."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, how did Richard Wagner achieve moments of extremely high volume in his operas?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a statement about how Richard Wagner achieved moments of extremely high volume in his operas that is supported by the text. The text states that European composers experimented with volume in their works by increasing the number of musicians in the orchestra and provides the example of Wagner, who “added more horns, trombones, and tubas to the orchestra.” The text explains that by having more of these instruments playing at the same time, the overall volume of the orchestra could be dramatically increased at key moments in Wagner’s operas."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never indicates that Wagner moved his operas indoors to achieve moments of extremely high volume, nor does it indicate that his operas were previously performed outdoors. The only technique discussed in the text for achieving extremely high volume is Wagner’s addition of more instruments to create a bigger, louder orchestra. Choice C is incorrect because the text never says that Wagner built or used a specially designed concert hall to increase volume through echoes. The only technique discussed in the text is Wagner’s addition of more instruments to create a bigger, louder orchestra. Choice D is incorrect because the text never mentions any special training for singers related to volume or singing for extended periods. The text’s focus is entirely on the orchestra and how Wagner and other European composers used instruments to experiment with volume in their musical works."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which statement about the difrasismo in cuauhtli in ocelotl is most strongly supported by the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a statement about the difrasismo in cuauhtli in ocelotl that is directly supported by the text. The text begins by describing difrasismo, a device used in Classical Nahuatl poetry. The text then mentions the device’s two functions: a formal one (giving structure to lines of verse) and a ritualistic one. The text indicates that the relation between the words in a difrasismo may appear tenuous without the additional information supplied by Aztec ceremonial culture but that the meaning becomes intelligible in the context of that information. Therefore, the difrasismo’s apparent obscurity can be resolved when considered in the proper cultural context."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate that the two nouns used in a difrasismo are semantically equivalent; instead, the text indicates that the two nouns used in a difrasismo make up a single metaphor whose meaning is often intelligible only in the context of information supplied by Aztec ceremonial culture."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t indicate that there’s a relationship between the formal function of the difrasismo and the difrasismo’s intelligibility. Additionally, the text suggests that present-day readers who are familiar with Aztec ceremonial culture wouldn’t find the difrasismo to be unintelligible. Choice D is incorrect because the text doesn’t indicate that the frequency of difrasismo’s use in Classical Nahuatl is a necessary feature of intelligibility: the text indicates that an infrequently used difrasismo would presumably also be intelligible to members of an Aztec audience who are sufficiently familiar with Aztec ceremonial culture."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. The text explains that economist Adam Smith’s famous metaphor of the invisible hand was putatively (that is, widely assumed but not proven) intended to illustrate a robust model (a consistently accurate generalization) of how individuals pursuing their own economic interests can create broader benefits for the population. The text then emphasizes the lack of affirmative evidence for this idea by calling out the term “putatively,” and explaining that, according to Gavin Kennedy, Smith used the metaphor only once in his works, in reference to specific circumstances related to the now-outdated economic view known as mercantilism, and that the metaphor didn’t garner much attention until economists in the twentieth century held it up as a paradigm (a theoretical framework in the field) and thereby implied that Smith shared some of their views on economics. By emphasizing “putatively,” the text implies that there is no independent reason to believe that Smith would agree with the metaphor’s use outside of the specific context for which he wrote it and that, therefore, the twentieth-century economists who used it did so to support their own views without regard for the metaphor’s importance to Smith’s work."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text indicates that Smith’s metaphor was largely ignored until some twentieth-century economists revived it and bolstered its status, the text suggests that the later economists used Smith’s metaphor to self-servingly boost their own work while ignoring the original context in which Smith wrote it. Moreover, the statement in this choice fails to reflect the text’s emphasis on Smith’s limited use of the metaphor in his work. Choice B is incorrect. Although the text indicates that some twentieth-century economists altered the significance of Smith’s metaphor, the text doesn’t suggest that the metaphor is a “useful model” of how aggregate benefits arise from individuals’ selfish actions, let alone that this usefulness is unaffected by taking the metaphor out of its original context. Choice C is incorrect. Although the text indicates that Smith’s metaphor was intended as a model of how individuals acting in their own interest produce aggregate benefits and it was written within the context of the now-outdated economic theory of mercantilism, these points are subordinate to the primary idea in the text, which is that Smith’s use of the metaphor was tightly constrained but twentieth-century economists ignored the original context so that they could use the metaphor to suggest, without support, that Smith would agree with their economic views."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the table that support the researchers’ claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it provides the most direct support from the table for the claim that two languages can convey similar amounts of information even if they’re spoken at different rates. The table shows the approximate rates at which five languages are spoken and the rates at which those five languages convey information. Vietnamese is spoken at around 5.3 syllables per second, whereas Spanish is spoken at around 7.7 syllables per second, but the two languages convey information at very similar rates: Vietnamese at a rate of around 42.5 bits per second and Spanish at a rate of around 42.0 bits per second. Thus, the description of Vietnamese conveying information at around the same rate that Spanish does despite being spoken more slowly supports the claim in the text that languages can convey the same amount of information even if spoken at different rates."}, {"type": "paragraph", "text": "Choice A is incorrect because it isn’t true that Thai and Hungarian have the lowest rates of speech of the five languages shown. According to the table, Hungarian is spoken at around 5.9 syllables per second, which is faster than Vietnamese (5.3 syllables per second). Additionally, even if this statement were true, the assertion that two languages are spoken the slowest and convey information the slowest wouldn’t support the claim that languages can convey the same amount of information even if they’re spoken at different rates. Choice C is incorrect because it isn’t true that the fastest-spoken language (Spanish, at 7.7 syllables per second) also conveys information the fastest: Spanish conveys information at 42.0 bits per second, which is slower than the 42.5 bits-per-second rate at which Vietnamese conveys information. Additionally, even if this statement were true, the assertion that the language spoken the fastest also conveys information the fastest has no bearing on the claim that languages can convey the same amount of information even if they’re spoken at different rates. Choice D is incorrect because it isn’t true that Serbian conveys information faster than Spanish does. According to the table, Serbian conveys information at a rate of around 39.1 bits per second, which is slower than the 42.0 bits-per-second rate at which Spanish conveys information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the table that support Barrett and Rayfield’s suggestion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it accurately describes data from the table that support Barrett and Rayfield’s suggestion about bite force estimates. According to the text, Barrett and Rayfield believe that estimates of dinosaur bite force may be strongly influenced by the methods used to produce them—that is, that different methods may produce significantly different results. The table shows that the studies by Bates and Falkingham and by Cost et al. used the same estimation method (muscular and skeletal modeling) and produced similar bite force estimates (approximately 35,000–57,000 newtons and 35,000–63,000 newtons, respectively). The study by Meers, however, used body-mass scaling and produced a much higher bite force estimate (183,000–235,000 newtons), while the study by Gignac and Erickson used tooth-bone interaction analysis and produced a much lower bite force estimate (8,000–34,000 newtons). The fact that one method produced similar estimates in two different studies and that two different methods used in other studies produced substantially different estimates supports the idea that dinosaur bite force estimates are significantly influenced by the methodology used to produce them."}, {"type": "paragraph", "text": "Choice A is incorrect because it inaccurately describes data from the table. The table does show that the studies by Meers and by Cost et al. used different estimation methods and produced very different ranges of estimated dinosaur bite force, which would support Barrett and Rayfield’s suggestion that different methodologies may produce significantly different estimates. However, the table doesn’t show that the study by Meers produced the lowest estimated maximum bite force while the study by Cost et al. produced the highest. In fact, the study by Meers estimated a maximum bite force of approximately 235,000 newtons, which is the highest of all the estimated maximums. Choice B is incorrect. Although the data from Gignac and Ericson’s study are accurately described, a single set of findings from one study using only one methodology can’t show that different methodologies may produce significantly different dinosaur bite force estimates, as Barrett and Rayfield suggest. Choice D is incorrect. Although the table shows that the maximum bite force estimated by Cost et al. was higher than that estimated by Bates and Falkingham, the difference is relatively small; in fact, both teams estimated a minimum bite force of approximately 35,000 newtons and a maximum bite force close to approximately 60,000 newtons. Because these findings demonstrate that a single methodology (muscular and skeletal modeling) produced similar overall results in two studies, the findings don’t support Barrett and Rayfield’s suggestion that different methodologies may produce significantly different dinosaur bite force estimates."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding from the researchers’ study, if true, would most strongly support their claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would most strongly support the researchers’ claim that they found evidence that experiencing awe can make people feel more connected to others and thus more likely to behave altruistically (with beneficial and unselfish concern for others). According to the text, the researchers tested for this effect by first having participants look at either something known to be awe-inspiring (very tall trees) or something ordinary (a plain building) and then purposely spilling pens near the participants. The finding that participants who had looked at the trees helped pick up significantly more pens than did participants who had looked at the building would support the researchers’ claim by demonstrating that the people who had experienced awe behaved more altruistically when the experimenter needed help than the other participants did."}, {"type": "paragraph", "text": "Choice B is incorrect because a finding about helpful participants using positive words to describe the trees and the building after the experiment was over wouldn’t have any bearing on the researchers’ claim that experiencing awe increases altruistic behavior. The text doesn’t address the use of positive words to describe things or suggest any connection between using such words and having experienced awe, so that behavior wouldn’t serve as evidence that experiencing awe played a role in promoting helpful behavior. Choice C is incorrect because a finding that participants who didn’t help the experimenter were significantly more likely than others to report having experienced awe whether they had looked at the building or the trees would weaken the researchers’ claim that experiencing awe increases altruistic behavior by suggesting that the opposite might be true—that experiencing awe is in fact linked to choosing not to act in a way that benefits someone else. Choice D is incorrect because a finding about participants noticing that the experimenter had dropped the pens wouldn’t have any bearing on the researchers’ claim about people behaving altruistically. Being aware of a challenge or problem isn’t necessarily beneficial on its own and isn’t the same as offering help, so the finding wouldn’t support the idea that experiencing awe increases altruistic behavior."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the sweet potato in Polynesia. The text indicates that the sweet potato is found in Polynesia but originated in South America, and that the sweet potato was being cultivated by Native Hawaiians and other Indigenous peoples in Polynesia long before sea voyages between South America and Polynesia began. The text goes on to note that research by Muñoz-Rodríguez and colleagues has established that the Polynesian varieties of sweet potato split from South American varieties more than 100,000 years ago, which is thousands of years before humans settled in Polynesia. If Polynesian peoples were cultivating the sweet potato before sea voyages between Polynesia and South America began, and if Polynesian varieties of sweet potato diverged from South American varieties well before people were in Polynesia, it can reasonably be concluded that humans didn’t play a role in bringing the sweet potato to Polynesia."}, {"type": "paragraph", "text": "Choice A is incorrect. The text doesn’t provide any information about when the sweet potato began to be cultivated in South America, so there’s no support for the conclusion that cultivation began in Polynesia before it began in South America. Choice B is incorrect because the text indicates that the sweet potato was being cultivated in Polynesia long before sea journeys between Polynesia and South America began. Therefore, it wouldn’t be reasonable to conclude that Polynesian peoples acquired the sweet potato from South American peoples. Additionally, the text indicates that the Polynesian varieties of sweet potato diverged from the South American varieties thousands of years before people settled in Polynesia, which suggests that the sweet potato was already present in Polynesia when people arrived. Choice D is incorrect because the text states that the domestic sweet potato, which is found in Polynesia, descends from a wild South American plant, not from a domesticated South American plant. The only people that the text describes as cultivating the sweet potato are Native Hawaiians and other Indigenous peoples of Polynesia."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the morphology (form and structure) of sea stars, a type of echinoderm. The text indicates that echinoderms have radially symmetrical body plans (symmetrical around a central point, usually in the form of a star), whereas most animals have bilaterally symmetrical body plans (symmetrical along an axis running from head to tail through a trunk). According to the text, sea stars are unusual echinoderms because, despite their radial body plan, they descended from known bilateral ancestors. This shift in body plan was thought to be a process of losing the genetic markers associated with the head region. The text explains that by comparing the genes of one sea star species (P. miniata) to those of a close relative, the acorn worm, researchers determined that instead, anterior (head) genes are active across the sea star’s entire body, posterior (tail) genes are active in limited, peripheral locations of the body, and no trunk-related genes are active. This finding strongly suggests that, rather than becoming “headless” as they evolved from a bilateral ancestor, sea stars developed a body plan consisting almost entirely of a head region with a minimal tail region and no trunk region present."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t identify how any particular region of sea stars’ bodies influences the layout of sea stars’ radial symmetry. Moreover, the text indicates that the radial symmetry of echinoderms is “usually starlike,” not that a starlike layout distinguishes sea stars from other echinoderms. Choice B is incorrect because the text doesn’t suggest that the idea that sea stars evolved from an ancestor with bilateral symmetry is incorrect (describing the bilateral origin as “known”) and doesn’t address any body plans other than those with radial or bilateral symmetry. The text strongly suggests that rather than revealing something about sea stars’ origin, Formery et al.’s findings contradict the assumption that the current body plan of sea stars is “headless.” Choice C is incorrect because the text suggests that Formery et al. were able to make determinations about P. miniata sea stars’ body plan based on the comparability of genetic markers between P. miniata and S. kowalevskii acorn worms. The text indicates only that little or no activity was observed in certain types of genes associated with body development in P. miniata, not that those genes turned out to largely differ from body-development genes in S. kowalevskii."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, “embryos”), and this choice supplies the clause with the finite present tense verb “enter” to indicate how the embryos achieve diapause."}, {"type": "paragraph", "text": "Choice B is incorrect because the nonfinite to-infinitive “to enter” doesn’t supply the main clause with a finite verb. Choice C is incorrect because the nonfinite participle “having entered” doesn’t supply the main clause with a finite verb."}, {"type": "paragraph", "text": "Choice D is incorrect because the nonfinite participle “entering” doesn’t supply the main clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past perfect verb “had doubled” properly indicates that the doubling of the organization’s initial membership occurred during a specific period before the present (between the organization’s founding in 1967 and the end of the 1990s)."}, {"type": "paragraph", "text": "Choice A is incorrect because the present perfect verb “has doubled” doesn’t indicate that the organization’s doubling of its initial membership occurred during a specific period in the past. Choice C is incorrect because the present tense verb “doubles” doesn’t indicate that the organization’s doubling of its initial membership occurred during a specific period in the past. Choice D is incorrect because the future tense verb “will double” doesn’t indicate that the organization’s doubling of its initial membership occurred during a specific period in the past."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after “percent” is used correctly to mark the boundary between one sentence (“After…percent”) and another (“Such… up”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice B is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join sentences. Choice D is incorrect because it results in a run-on sentence. The sentences (“After…percent” and “Such…up”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is finite verb use in a main clause. A main clause requires a finite verb to perform the action of the subject (in this case, Ashford’s “gestures” and “habit”), and this choice supplies the finite past tense verb “helped” to indicate what Ashford’s gestures and habit helped accomplish."}, {"type": "paragraph", "text": "Choice B is incorrect because the non-finite participle “helping” doesn’t supply the main clause with a finite verb. Choice C is incorrect because the relative clause “that helped” doesn’t supply the main clause with a finite verb. Choice D is incorrect because the non-finite to-infinitive “to help” doesn’t supply the main clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The dash after “Springs” pairs with the dash after “earth” to separate the supplementary element “in this case, the porous rocks of the hills around Hot Springs” from the rest of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a colon can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a comma can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon is used in a conventional way to introduce the following description of how the number of jams available varied."}, {"type": "paragraph", "text": "Choice B is incorrect because it creates a comma splice. A comma can’t be used in this way to join two main clauses (“the number…varied” and “some…six”)."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in an illogical and confusing sentence. Using the conjunction “while” to join the main clause (“the number…varied”) with the following clause’s description of the number of jams available suggests that the variation in the number of jams is in contrast to some shoppers having twenty-four options. Choice D is incorrect because it results in an illogical and confusing sentence. Using “while” in this way suggests that the number of jams available varied during the time in which some shoppers had twenty-four options and others had six. The sentence makes clear, however, that what follows “varied” is a description of the variation, not a separate, simultaneous occurrence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). In this choice, the semicolon after “Lagos” is conventionally used to separate the first item (“The Joys…Lagos”) and the second item (“A Kind…Nigeria”) in the series. Further, the comma after “Marriage” correctly separates the title “A Kind of Marriage” from the supplementary phrase (“a television…Nigeria”) that describes it."}, {"type": "paragraph", "text": "Choice A is incorrect because the comma after “Lagos” doesn’t match the semicolon used later in the series to separate the second item (“A Kind…Nigeria”) from the third item (“and…autobiography”). Choice C is incorrect because the comma after “Lagos” doesn’t match the semicolon used later in the series to separate the second item (“A Kind…Nigeria”) from the third item (“and… autobiography”). Additionally, a colon can’t be used in this way to separate the title “A Kind of Marriage” from the supplementary phrase (“a television…Nigeria”) that describes it. Choice D is incorrect because it fails to use appropriate punctuation to separate the title “A Kind of Marriage” from the supplementary phrase (“a television…Nigeria”) that describes it."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “though” from the preceding main clause (“Jetties can sometimes have the opposite effect”) and uses a semicolon to join the next main clause (“obstructing…areas”) to the rest of the sentence. Further, placing the semicolon after “though” logically indicates that the information earlier in this sentence (that jetties can sometimes cause erosion) is contrary to what might be assumed from the information in the previous sentence (that jetties are often constructed for the purpose of protecting coastlines from erosion)."}, {"type": "paragraph", "text": "Choice B is incorrect because it fails to mark the boundary between the two main clauses with appropriate punctuation. With “though…areas” functioning as a subordinate clause following the comma, this choice illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following “though” supports the previous claim about the erosive effects of jetties. Choice C is incorrect because it’s not conventional to use a semicolon in this way to separate a main clause from a dependent clause. Further, it illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following “though” supports the previous claim about the erosive effects of jetties. Choice D is incorrect because it results in a comma splice. Commas can’t be used in this way to set off a supplementary word or phrase between two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “In fact” logically signals that the information in this sentence about the large number of recordings in ANLA’s collection emphasizes and supports the previous claim that ANLA is known for its impressive audio collection."}, {"type": "paragraph", "text": "Choice B is incorrect because “after” illogically signals that the information in this sentence occurs later in a sequence of events than the previous claim about ANLA’s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice C is incorrect because “regardless” illogically signals that the information in this sentence is true despite the previous claim about ANLA’s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice D is incorrect because “instead” illogically signals that the information in this sentence presents an alternative to the previous claim about ANLA’s impressive audio collection. Rather, the information about the large number of recordings emphasizes and supports that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Currently” logically signals that the archaeologists’ use of drones (a current technology) to photograph the lines is the present-day continuation of the ongoing archaeological research described in the previous sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because “in comparison” illogically signals that the action described in this sentence offers a comparison to the ongoing archaeological research described in the previous sentence. Instead, the use of drones is the present-day continuation of that research. Choice C is incorrect because “still” illogically signals that the action described in this sentence occurs despite the ongoing archaeological research described in the previous sentence. Instead, the use of drones is the present-day continuation of that research. Choice D is incorrect because “however” illogically signals that the action described in this sentence occurs either despite or in contrast to the ongoing archaeological research described in the previous sentence. Instead, the use of drones is the present-day continuation of that research."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “By contrast” logically signals that the information in this sentence—that dogs can see, hear, and smell by the end of two weeks— contrasts with the preceding information (that wolves can smell but not see or hear at the same age)."}, {"type": "paragraph", "text": "Choice A is incorrect because “in other words” illogically signals that the information about domesticated dogs in this sentence paraphrases the information about wolves in the previous sentence. Instead, the information about dogs contrasts with what came before. Choice B is incorrect because “for instance” illogically signals that the information about domesticated dogs in this sentence exemplifies the information about wolves in the previous sentence. Instead, the information about dogs contrasts with what came before. Choice D is incorrect because “accordingly” illogically signals that the information about domesticated dogs in this sentence is in accordance with, or results from, the information about wolves in the previous sentence. Instead, the information about dogs contrasts with what came before."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “On the contrary” logically signals that the information in this sentence—that Dies Irae’s appearance of depth is merely an illusion—contrasts with the previous statement about a viewer’s possible assumption regarding the street painting."}, {"type": "paragraph", "text": "Choice A is incorrect because “additionally” illogically signals that this sentence is simply additional information about a viewer’s possible assumption regarding the street painting. Instead, the information about how Wenner achieved the illusion of depth contrasts with the previous sentence’s description of the illusion."}, {"type": "paragraph", "text": "Choice C is incorrect because “as a result” illogically signals that the information in this sentence is a result of, or caused by, a viewer’s possible assumption regarding the street painting. Instead, the information about how Wenner achieved the illusion of depth contrasts with the previous sentence’s description of the illusion. Choice D is incorrect because “next” illogically signals that the information in this sentence is the next step in a process. Instead, the information about how Wenner achieved the illusion of depth contrasts with the previous sentence’s description of the illusion."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “As such” correctly signals that the claim in this sentence—that Ostrom’s work is a repudiation of the “tragedy of the commons” view—follows logically from the information about Ostrom’s studies in the previous sentence. According to that sentence, Ostrom’s studies demonstrate that common pool resources can in fact be sustainably managed by the people who use them."}, {"type": "paragraph", "text": "Choice A is incorrect because “by contrast” illogically signals that the information in this sentence contrasts with the information about Ostrom’s studies in the previous sentence. Instead, the claim that Ostrom’s work repudiates the “tragedy of the commons” view follows logically from that information. Choice B is incorrect because “for example” illogically signals that the claim in this sentence exemplifies the information about Ostrom’s studies in the previous sentence. Instead, the claim that Ostrom’s work repudiates the “tragedy of the commons” view follows logically from that information. Choice C is incorrect because “that said” illogically signals that the information in this sentence is an exception or caveat to the information about Ostrom’s studies in the previous sentence. Instead, the claim that Ostrom’s work repudiates the “tragedy of the commons” view follows logically from that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence effectively explains an advantage of infilling: it’s less invasive than using a power grinder."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence identifies a disadvantage of power grinding; it doesn’t explain an advantage of infilling. Choice C is incorrect. The sentence identifies the two techniques park rangers use; it doesn’t explain an advantage of infilling. Choice D is incorrect. The sentence indicates that power grinding and infilling are different in one aspect; it fails to explain an advantage of infilling."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence emphasizes the role a misconception played in the naming of a place, explaining that Spanish explorers mistook a peninsula for an island and, as a result, named the peninsula after a fictional island, California."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence mentions a novel that featured a fictional island, California; it doesn’t emphasize the role a misconception played in the naming of a place. Choice B is incorrect. The sentence notes that Baja California was originally named after a fictional place; it doesn’t emphasize the role a misconception—specifically, the Spanish explorers’ mistaken belief that the peninsula was an island—played in the naming of a place. Choice C is incorrect. The sentence indicates when Spanish explorers learned of the peninsula they called California; it doesn’t emphasize the role a misconception played in the naming of a place."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 8: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-8-math') then
    raise notice 'skipping sat-practice-test-8-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-8-math', 'SAT Practice Test 8: Math', 'Official SAT Practice Test 8 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 217, '[[200, 200], [210, 230], [210, 240], [210, 250], [210, 260], [210, 270], [210, 280], [210, 290], [220, 300], [230, 310], [260, 340], [290, 350], [320, 360], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [490, 550], [500, 560], [510, 570], [520, 580], [540, 600], [550, 610], [560, 620], [570, 630], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 720], [670, 730], [690, 750], [710, 770], [740, 780], [760, 790], [770, 800], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A bus is traveling at a constant speed along a straight portion of road. The equation $d = 30t$ gives the distance $d$, in feet from a road marker, that the bus will be $t$ seconds after passing the marker. How many feet from the marker will the bus be $2$ seconds after passing the marker?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$d = 30(2) = 60$ feet."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For a particular machine that produces beads, $29$ out of every $100$ beads it produces have a defect. A bead produced by the machine will be selected at random. What is the probability of selecting a bead that has a defect?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$29$ of every $100$ beads are defective, so the probability is $\\tfrac{29}{100}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q03.png", "alt": "Figure for question 3", "width": 255}, {"type": "paragraph", "text": "What is the $y$-intercept of the graph shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The curve crosses the $y$-axis at $y = 8$, so the $y$-intercept is $(0, 8)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(2x^2 + x - 9) + (x^2 + 6x + 1)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Combine like terms: $3x^2 + 7x - 8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An analyst collected data on the price of a carton of grape tomatoes at $30$ locations selected at random in Utah. The mean price of a carton of grape tomatoes in Utah was estimated to be $\\$4.23$, with an associated margin of error of $\\$0.08$. Which of the following is a plausible statement about the mean price of a carton of grape tomatoes for all locations that sell this product in Utah?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The plausible values are the estimate plus or minus the margin of error: $4.23 \\pm 0.08$, from $\\$4.15$ to $\\$4.31$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2.6 + x = 2.8"}, {"type": "paragraph", "text": "What value of $x$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 2.8 - 2.6 = 0.2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['0.2', '1/5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Out of $300$ seeds that were planted, $80\\%$ sprouted. How many of these seeds sprouted?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.80 \\times 300 = 240$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 7, 'spr', array['240']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 4x + b"}, {"type": "paragraph", "text": "For the linear function $f$, $b$ is a constant and $f(7) = 28$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4(7) + b = 28$, so $b = 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Right triangles $LMN$ and $PQR$ are similar, where $L$ and $M$ correspond to $P$ and $Q$, respectively. Angle $M$ has a measure of $53^\\circ$. What is the measure of angle $Q$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Corresponding angles of similar triangles are equal, so angle $Q$ measures $53^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the equation of the line that passes through the point $(0, 5)$ and is parallel to the graph of $y = 7x + 4$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A parallel line has the same slope, $7$, and the $y$-intercept $5$: $y = 7x + 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q11.png", "alt": "Figure for question 11", "width": 256}, {"type": "paragraph", "text": "Which of the following equations is the most appropriate linear model for the data shown in the scatterplot?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The points fall from about $10$ near $x = 0$, so the model needs a negative slope and a positive $y$-intercept near $10$: $y = -1.9x + 10.1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A model predicts that the population of Bergen was $15{,}000$ in $2005$. The model also predicts that each year for the next $5$ years, the population $p$ increased by $4\\%$ of the previous year''s population. Which equation best represents this model, where $x$ is the number of years after $2005$, for $x \\le 5$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Starting at $15{,}000$ and growing by $4\\%$ a year multiplies by $1.04$ each year: $p = 15{,}000(1.04)^x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 2a + 8b &= 198 \\\\ 2a + 4b &= 98 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(a, b)$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract the second equation from the first: $4b = 100$, so $b = 25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['25']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The expression $90y^5 - 54y^4$ is equivalent to $ry^4(15y - 9)$, where $r$ is a constant. What is the value of $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$ry^4(15y - 9) = 15ry^5 - 9ry^4$. Matching $15r = 90$ (and $9r = 54$) gives $r = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['6']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q15.png", "alt": "Figure for question 15", "width": 248}, {"type": "paragraph", "text": "The graph of $y = f(x)$ is shown, where the function $f$ is defined by $f(x) = ax^3 + bx^2 + cx + d$ and $a$, $b$, $c$, and $d$ are constants. For how many values of $x$ does $f(x) = 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = 0$ where the graph meets the $x$-axis. It crosses at three points (near $0$, $4$, and $7$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The area $A$, in square centimeters, of a rectangular cutting board can be represented by the expression $w(w + 9)$, where $w$ is the width, in centimeters, of the cutting board. Which expression represents the length, in centimeters, of the cutting board?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Area $=$ width $\\times$ length, and the width is $w$, so the length is $w + 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "p = \\frac{k}{4j + 9}"}, {"type": "paragraph", "text": "The given equation relates the distinct positive numbers $p$, $k$, and $j$. Which equation correctly expresses $4j + 9$ in terms of $p$ and $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Multiply both sides by $4j + 9$ and divide by $p$: $4j + 9 = \\dfrac{k}{p}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Circle $A$ has a radius of $3n$ and circle $B$ has a radius of $129n$, where $n$ is a positive constant. The area of circle $B$ is how many times the area of circle $A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The radius of $B$ is $43$ times the radius of $A$, so its area is $43^2 = 1{,}849$ times as large."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The measure of angle $R$ is $\\dfrac{2\\pi}{3}$ radians. The measure of angle $T$ is $\\dfrac{5\\pi}{12}$ radians greater than the measure of angle $R$. What is the measure of angle $T$, in **degrees**?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$T = \\dfrac{2\\pi}{3} + \\dfrac{5\\pi}{12} = \\dfrac{13\\pi}{12}$ radians $= \\dfrac{13}{12} \\times 180^\\circ = 195^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = x^2 - 14x + 22"}, {"type": "paragraph", "text": "The given equation relates the variables $x$ and $y$. For what value of $x$ does the value of $y$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The parabola opens upward, with vertex at $x = -\\dfrac{-14}{2(1)} = 7$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 20, 'spr', array['7']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A small business owner budgets $\\$2{,}200$ to purchase candles. The owner must purchase a minimum of $200$ candles to maintain the discounted pricing. If the owner pays $\\$4.90$ per candle to purchase small candles and $\\$11.60$ per candle to purchase large candles, what is the maximum number of large candles the owner can purchase to stay within the budget and maintain the discounted pricing?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "To maximize large candles, buy exactly $200$ in total: $L$ large and $200 - L$ small. Then $4.90(200 - L) + 11.60L \\le 2{,}200$, so $980 + 6.70L \\le 2{,}200$ and $L \\le 182.08\\ldots$. The maximum is $182$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 21, 'spr', array['182']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &\\le x + 7 \\\\ y &\\ge -2x - 1 \\end{aligned}"}, {"type": "paragraph", "text": "Which point $(x, y)$ is a solution to the given system of inequalities in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "For $(14, 0)$: $0 \\le 21$ and $0 \\ge -29$, both true. Each other point fails one inequality."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q23.png", "alt": "Figure for question 23", "width": 194}, {"type": "paragraph", "text": "The frequency table summarizes a data set of the weights, rounded to the nearest pound, of $71$ tortoises. A weight of $39$ pounds is added to the original data set, creating a new data set of the weights, rounded to the nearest pound, of $72$ tortoises. Which statement best compares the mean and median of the new data set to the mean and median of the original data set?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$39$ is above every original value, so the mean increases. The original median is the $36$th value; the cumulative counts are $12, 20, 25, 32, 41$, so the $36$th and $37$th values are both $17$. The new median (average of the $36$th and $37$th) is still $17$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x - 29 = (x - a)(x - 29)"}, {"type": "paragraph", "text": "Which of the following are solutions to the given equation, where $a$ is a constant and $a > 30$?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } a \\\\ &\\text{II. } a + 1 \\\\ &\\text{III. } 29 \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 29$ makes both sides $0$. Otherwise divide by $x - 29$: $1 = x - a$, so $x = a + 1$. Checking $x = a$ gives $a - 29 = 0$, false since $a > 30$. So II and III only."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In the $xy$-plane, the graph of the equation $y = -x^2 + 9x - 100$ intersects the line $y = c$ at exactly one point. What is the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A horizontal line meets a parabola once only at the vertex. The vertex is at $x = \\tfrac{9}{2}$, where $y = -\\tfrac{81}{4} + \\tfrac{81}{2} - 100 = -\\tfrac{319}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The functions $f$ and $g$ are defined by the given equations, where $x \\ge 0$. Which of the following equations displays, as a constant or coefficient, the maximum value of the function it defines, where $x \\ge 0$?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } f(x) = 18(1.25)^x + 41 \\\\ &\\text{II. } g(x) = 9(0.73)^x \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f$ grows without bound, so it has no maximum. $g$ decreases for $x \\ge 0$, so its maximum is $g(0) = 9$, which appears as the coefficient. Only II."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The perimeter of an equilateral triangle is $852$ centimeters. The three vertices of the triangle lie on a circle. The radius of the circle is $w\\sqrt{3}$ centimeters. What is the value of $w$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each side is $284$. The radius of the circle through the vertices of an equilateral triangle is $\\dfrac{s}{\\sqrt{3}} = \\dfrac{284}{\\sqrt{3}} = \\dfrac{284\\sqrt{3}}{3}$, so $w = \\dfrac{284}{3}$ (about $94.67$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['284/3', '94.66', '94.67']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q01.png", "alt": "Figure for question 1", "width": 266}, {"type": "paragraph", "text": "What is the $y$-intercept of the line graphed?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line crosses the $y$-axis at $y = 5$, so the $y$-intercept is $(0, 5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["Type of store", "Average number of employees"], "rows": [["Warehouse store", "$365$"], ["Department store", "$213$"], ["Supermarket", "$130$"]]}, {"type": "paragraph", "text": "For a certain region, the table shows the average number of store employees in $2016$ by type of store. Based on the table, how much greater was the average number of store employees in warehouse stores than in supermarkets?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$365 - 130 = 235$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q03.png", "alt": "Figure for question 3", "width": 234}, {"type": "paragraph", "text": "In the figure, line $m$ is parallel to line $n$, and line $t$ intersects both lines. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $33^\\circ$ angle at line $n$ corresponds to the acute angle at line $m$ on the same side of $t$. Angle $x$ forms a straight line with that acute angle, so $x = 180 - 33 = 147$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Sean rents a tent at a cost of $\\$11$ per day plus a onetime insurance fee of $\\$10$. Which equation represents the total cost $c$, in dollars, to rent the tent with insurance for $d$ days?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\$11$ for each of $d$ days is $11d$, plus the one-time $\\$10$: $c = 11d + 10$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q05.png", "alt": "Figure for question 5", "width": 291}, {"type": "paragraph", "text": "For the right triangle shown, $a = 4$ and $b = 5$. Which expression represents the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "By the Pythagorean theorem, $c^2 = a^2 + b^2$, so $c = \\sqrt{4^2 + 5^2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = 6x$. For what value of $x$ is $g(x) = 54$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$6x = 54$, so $x = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 8x^3 + 4$. What is the value of $f(2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(2) = 8(8) + 4 = 68$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['68']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = \\dfrac{1}{10}x - 2$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = -2$, so the $y$-intercept is $(0, -2)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A producer is creating a video with a length of $70$ minutes. The video will consist of segments that are $1$ minute long and segments that are $3$ minutes long. Which equation represents this situation, where $x$ represents the number of $1$-minute segments and $y$ represents the number of $3$-minute segments?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $1$-minute segments take $x$ minutes and the $3$-minute segments take $3y$ minutes: $x + 3y = 70$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 7x^3$. In the $xy$-plane, the graph of $y = g(x)$ is the result of shifting the graph of $y = f(x)$ down $2$ units. Which equation defines function $g$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Shifting down $2$ units subtracts $2$ from every output: $g(x) = 7x^3 - 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= -3x \\\\ 4x + y &= 15 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $4x - 3x = 15$, so $x = 15$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q12.png", "alt": "Figure for question 12", "width": 302}, {"type": "paragraph", "text": "In the right triangle shown, what is the value of $\\sin A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sin A = \\dfrac{\\text{opposite}}{\\text{hypotenuse}} = \\dfrac{BC}{AB} = \\dfrac{35}{171}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the area, in square centimeters, of a rectangle with a length of $34$ centimeters (cm) and a width of $29$ cm?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$34 \\times 29 = 986$ square centimeters."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 13, 'spr', array['986']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $\\dfrac{x}{y} = 4$ and $\\dfrac{24x}{ny} = 4$, what is the value of $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{24x}{ny} = \\dfrac{24}{n} \\cdot \\dfrac{x}{y} = \\dfrac{96}{n} = 4$, so $n = 24$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 14, 'spr', array['24']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A bowl contains $20$ ounces of water. When the bowl is uncovered, the amount of water in the bowl decreases by $1$ ounce every $4$ days. If $9$ ounces of water remain in this bowl, for how many days has it been uncovered?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$20 - 9 = 11$ ounces have evaporated, at $4$ days per ounce: $11 \\times 4 = 44$ days."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $9(4 - 3x) + 2 = 8(4 - 3x) + 18$, what is the value of $4 - 3x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Let $u = 4 - 3x$: $9u + 2 = 8u + 18$, so $u = 16$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A certain township consists of a $5$-hectare industrial park and a $24$-hectare neighborhood. The total number of trees in the township is $4{,}529$. The equation $5x + 24y = 4{,}529$ represents this situation. Which of the following is the best interpretation of $x$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x$ is the number of trees in the $5$-hectare industrial park, so $x$ is the average number of trees per hectare there."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $a^{\\frac{11}{12}}$, where $a > 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt[144]{a^{132}} = a^{132/144} = a^{11/12}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q19.png", "alt": "Figure for question 19", "width": 309}, {"type": "paragraph", "text": "The dot plots represent the distributions of values in data sets A and B."}, {"type": "paragraph", "text": "Which of the following statements must be true?"}, {"type": "paragraph", "text": "I. The median of data set A is equal to the median of data set B."}, {"type": "paragraph", "text": "II. The standard deviation of data set A is equal to the standard deviation of data set B."}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each set has $17$ values, so the median is the $9$th. Counting dots from the left, the $9$th value is $13$ in both sets, so I is true. The sets are spread differently (B has more values at the ends), so their standard deviations are not equal."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle has center $O$, and points $R$ and $S$ lie on the circle. In triangle $ORS$, the measure of $\\angle ROS$ is $88^\\circ$. What is the measure of $\\angle RSO$, in degrees? (Disregard the degree symbol when entering your answer.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$OR$ and $OS$ are radii, so the triangle is isosceles and its base angles are equal: $\\dfrac{180 - 88}{2} = 46$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['46']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The regular price of a shirt at a store is $\\$11.70$. The sale price of the shirt is $80\\%$ less than the regular price, and the sale price is $30\\%$ greater than the store''s cost for the shirt. What was the store''s cost, in dollars, for the shirt? (Disregard the $\\$$ sign when entering your answer. For example, if your answer is $\\$4.97$, enter $4.97$)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The sale price is $0.20 \\times 11.70 = 2.34$ dollars, which is $1.30$ times the cost. So the cost is $2.34 \\div 1.30 = 1.80$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 21, 'spr', array['1.8', '9/5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A cube has an edge length of $68$ inches. A solid sphere with a radius of $34$ inches is inside the cube, such that the sphere touches the center of each face of the cube. To the nearest cubic inch, what is the volume of the space in the cube **not** taken up by the sphere?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Cube: $68^3 = 314{,}432$. Sphere: $\\tfrac{4}{3}\\pi(34)^3 \\approx 164{,}636$. The difference is about $149{,}796$ cubic inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = 6x + 18"}, {"type": "paragraph", "text": "One of the equations in a system of two linear equations is given. The system has no solution. Which equation could be the second equation in the system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "No solution means a parallel line with a different intercept. $-6x + y = 22$ is $y = 6x + 22$: same slope $6$, different intercept."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangles $PQR$ and $LMN$ are graphed in the $xy$-plane. Triangle $PQR$ has vertices $P$, $Q$, and $R$ at $(4, 5)$, $(4, 7)$, and $(6, 5)$, respectively. Triangle $LMN$ has vertices $L$, $M$, and $N$ at $(4, 5)$, $(4, 7 + k)$, and $(6 + k, 5)$, respectively, where $k$ is a positive constant. If the measure of $\\angle Q$ is $t^\\circ$, what is the measure of $\\angle N$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Both triangles have a right angle at $(4, 5)$ and two equal legs ($2$ and $2$; $2 + k$ and $2 + k$), so both are isosceles right triangles. Angles $Q$ and $N$ are complementary acute angles of such triangles, so $\\angle N = (90 - t)^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 2x + 3y &= 7 \\\\ 10x + 15y &= 35 \\end{aligned}"}, {"type": "paragraph", "text": "For each real number $r$, which of the following points lies on the graph of each equation in the $xy$-plane for the given system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The second equation is $5$ times the first, so both describe the line $2x + 3y = 7$. If $y = r$, then $x = \\dfrac{7 - 3r}{2} = -\\dfrac{3r}{2} + \\dfrac{7}{2}$, which is choice B."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\frac{x^2}{\\sqrt{x^2 - c^2}} = \\frac{c^2}{\\sqrt{x^2 - c^2}} + 39"}, {"type": "paragraph", "text": "In the given equation, $c$ is a positive constant. Which of the following is one of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract: $\\dfrac{x^2 - c^2}{\\sqrt{x^2 - c^2}} = \\sqrt{x^2 - c^2} = 39$, so $x^2 = c^2 + 39^2$ and $x = \\pm\\sqrt{c^2 + 39^2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The quadratic function $g$ models the depth, in meters, below the surface of the water of a seal $t$ minutes after the seal entered the water during a dive. The function estimates that the seal reached its maximum depth of $302.4$ meters $6$ minutes after it entered the water and then reached the surface of the water $12$ minutes after it entered the water. Based on the function, what was the estimated depth, to the nearest meter, of the seal $10$ minutes after it entered the water?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g(t) = a(t - 6)^2 + 302.4$ with $g(12) = 0$: $36a = -302.4$, so $a = -8.4$. Then $g(10) = -8.4(16) + 302.4 = 168$ meters."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['168']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
