    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 12);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-08/rw-m1-q13.png", "alt": "Table or graph for this question", "width": 297}, {"type": "paragraph", "text": "When construction of a single-family house begins, it is called a housing start. In the first four months of 2022, the highest number of housing starts in the United States was in ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
