    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The Philadelphia and Lancaster Turnpike was a road built between 1792 and 1794.", "It was the first private turnpike in the United States.", "It connected the cities of Philadelphia and Lancaster in the state of Pennsylvania.", "It was sixty-two miles long."]}, {"type": "paragraph", "text": "The student wants to emphasize the distance covered by the Philadelphia and Lancaster Turnpike."}]}'::jsonb, 'source') returning id into v_stim;
