    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Most, but not all, of the Moon’s oxygen comes from the Sun, via solar wind.", "Cosmochemist Kentaro Terada from Osaka University wondered if some of the unaccounted-for oxygen could be coming from Earth.", "In 2008, he analyzed data from the Japanese satellite Kaguya.", "Kaguya gathered data about gases and particles it encountered while orbiting the Moon.", "Based on the Kaguya data, Terada confirmed his suspicion that Earth is sending oxygen to the Moon."]}, {"type": "paragraph", "text": "The student wants to emphasize the aim of the research study."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "As it orbited the Moon, the Kaguya satellite collected data that was later analyzed by cosmochemist Kentaro Terada."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Before 2008, Kentaro Terada wondered if the Moon was receiving some of its oxygen from Earth."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Cosmochemist Kentaro Terada set out to determine whether some of the Moon’s oxygen was coming from Earth."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Kentaro Terada’s study determined that Earth is sending a small amount of oxygen to the Moon."}]}'::jsonb, false);
