    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The factors that affect clutch size (the number of eggs laid at one time) have been well studied in birds but not in lizards.", "A team led by Shai Meiri of Tel Aviv University investigated which factors influence lizard clutch size.", "Meiri’s team obtained clutch-size and habitat data for over 3,900 lizard species and analyzed the data with statistical models.", "Larger clutch size was associated with environments in higher latitudes that have more seasonal change.", "Lizards in higher-latitude environments may lay larger clutches to take advantage of shorter windows of favorable conditions."]}, {"type": "paragraph", "text": "The student wants to emphasize the aim of the research study."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Researchers wanted to know which factors influence lizard egg clutch size because such factors have been well studied in birds but not in lizards."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "After they obtained data for over 3,900 lizard species, researchers determined that larger clutch size was associated with environments in higher latitudes that have more seasonal change."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "We now know that lizards in higher-latitude environments may lay larger clutches to take advantage of shorter windows of favorable conditions."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Researchers obtained clutch-size and habitat data for over 3,900 lizard species and analyzed the data with statistical models."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 32);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["British musicians John Lennon and Paul McCartney shared writing credit for numerous Beatles songs.", "Many Lennon-McCartney songs were actually written by either Lennon or McCartney, not by both.", "The exact authorship of specific parts of many Beatles songs, such as the verse for “In My Life,” is disputed.", "Mark Glickman, Jason Brown, and Ryan Song used statistical methods to analyze the musical content of Beatles songs.", "They concluded that there is 18.9% probability that McCartney wrote the verse for “In My Life,” stating that the verse is “consistent with Lennon’s songwriting style.”"]}, {"type": "paragraph", "text": ""}, {"type": "paragraph", "text": "If you finish before time is called, you may check your work on this module only."}, {"type": "paragraph", "text": "Do not turn to any other module in the test."}, {"type": "paragraph", "text": "The student wants to make a generalization about the kind of study conducted by Glickman, Brown, and Song."}]}'::jsonb, 'source') returning id into v_stim;
